                     wm:hasCategory ?holding_category_uri .
            ?investor wm:investorId ?investorId .
            ?holding_category_uri rdfs:label ?holding_category .
        }
        GROUP BY ?investorId
    }

    BIND(
        IF(
            CONTAINS(?holding_categories, ?profile_category),
            "represented_by_holding",
            "not_represented_by_holding"
