WHERE {
  {
    SELECT ?investor ?investorId ?investorName
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:investorName ?investorName ;
                wm:hasPortfolioHealth ?health .
      ?health wm:diversificationScore ?diversificationScoreRaw .
      BIND(xsd:decimal(?diversificationScoreRaw) AS ?diversificationScore)
      FILTER(?diversificationScore < 30)
    }
    GROUP BY ?investor ?investorId ?investorName
  }

  ?investor wm:hasInvestmentGoal ?goal .
  ?goal wm:shortfall ?shortfallRaw .
  BIND(xsd:decimal(?shortfallRaw) AS ?shortfall)
}
GROUP BY ?investorId ?investorName
