PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?timeHorizon
    (SUM(?preTotalCashFlow) AS ?totalCashFlow)
    (SUM(?preTotalRebalancingAmount) AS ?totalRebalancingAmount)
    (SUM(?preScenarioCount) AS ?scenarioChangeCount)
    (AVG(?preAvgRiskScore) AS ?avgRiskScore)
    (AVG(?preAvgGoalMatchPct) AS ?avgGoalMatchPct)
WHERE {
    {
        SELECT
            ?investorId
            ?date
            ?timeHorizon
            (SUM(xsd:decimal(?amount)) AS ?preTotalCashFlow)
            (SUM(xsd:decimal(?rebalanceAmount)) AS ?preTotalRebalancingAmount)
            (COUNT(DISTINCT ?scenario) AS ?preScenarioCount)
            (AVG(xsd:decimal(?riskScore)) AS ?preAvgRiskScore)
            (AVG(xsd:decimal(?goalMatchPct)) AS ?preAvgGoalMatchPct)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:timeHorizon ?timeHorizon .

            OPTIONAL {
                ?cashFlow rdf:type wm:CashFlow ;
                          wm:cashFlowOfInvestor ?investor ;
                          wm:amount ?amount ;
                          wm:date ?date .
            }

            OPTIONAL {
                ?rebalancing rdf:type wm:RebalancingAction ;
                             wm:rebalancingActionOfInvestor ?investor ;
                             wm:amount ?rebalanceAmount .
            }

            OPTIONAL {
                ?scenarioRebalancing rdf:type wm:ScenarioRebalancing ;
                                     wm:scenarioRebalancingOfInvestor ?investor ;
                                     wm:scenario ?scenario .
            }

            OPTIONAL {
                ?portfolioHealth rdf:type wm:PortfolioHealth ;
                                 wm:healthOfInvestor ?investor ;
                                 wm:riskScore ?riskScore ;
                                 wm:goalMatchPct ?goalMatchPct .
            }
        }
        GROUP BY ?investorId ?date ?timeHorizon
    }
}
GROUP BY ?timeHorizon

