                    wm:liquidityScore ?liquidityScore .

            FILTER(xsd:decimal(?riskScore) > 70) .
            FILTER(xsd:decimal(?liquidityScore) < 30) .

            {
                SELECT ?investor (COUNT(?holding) AS ?hasNegativeReturn) WHERE {
                    ?investor wm:hasHolding ?holding .
                    ?holding wm:returnsPct ?returnsPct .
                    FILTER(xsd:decimal(?returnsPct) < 0) .
                }
                GROUP BY ?investor
                HAVING(COUNT(?holding) > 0)
            }

            {
                SELECT ?investor (COUNT(?allocation) AS ?hasHighAllocation) WHERE {
                    ?investor wm:hasSectorAllocation ?allocation .
                    ?allocation wm:allocationPct ?allocationPct .
                    FILTER(xsd:decimal(?allocationPct) > 30) .
                }
                GROUP BY ?investor
                HAVING(COUNT(?allocation) > 0)
            }
        }
        GROUP BY ?investor ?investorId
    }

    ?investor wm:investorName ?investorName .
}

