PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?category
    (SUM(?rebalancingAmount) AS ?totalRebalancingAmount)
    (SUM(?cashFlowAmount) AS ?totalCashFlowAmount)
    (SUM(?transactionCount) AS ?totalTransactionCount)
WHERE {
    {
        SELECT
            ?investorId
            (COALESCE(?investorCategory, "NULL") AS ?category)
            (SUM(xsd:decimal(?raAmount)) AS ?rebalancingAmount)
            (COUNT(DISTINCT ?raId) AS ?rebalancingCount)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId .
            OPTIONAL { ?investor wm:category ?investorCategory . }
            OPTIONAL {
                ?ra rdf:type wm:RebalancingAction ;
                    wm:rebalancingActionOfInvestor ?investor ;
                    wm:amount ?raAmount ;
                    wm:rebalanceId ?raId .
            }
        }
        GROUP BY ?investorId ?investorCategory
    }
    {
        SELECT
            ?investorId
            (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
            (COUNT(DISTINCT ?cfId) AS ?cashFlowCount)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId .
            OPTIONAL {
                ?cf rdf:type wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cfAmount ;
                    wm:cashFlowId ?cfId .
            }
        }
        GROUP BY ?investorId
    }
    BIND((?rebalancingCount + ?cashFlowCount) AS ?transactionCount)
}
GROUP BY ?category

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER NOT EXISTS {
    ?investor wm:hasCategory ?category .
  }
  FILTER NOT EXISTS {
    ?cashFlow rdf:type wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor .
  }
  FILTER NOT EXISTS {
    ?holding rdf:type wm:PortfolioHolding ;
             wm:heldByInvestor ?investor .
  }
  FILTER NOT EXISTS {
    ?health rdf:type wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investor
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:timeHorizon "Short-term" ;
                      wm:investorId ?investorId .

            ?holding rdf:type wm:PortfolioHolding ;
                     wm:investmentType "Private Equity" ;
                     wm:heldByInvestor ?investor .
        }
        GROUP BY ?investor
    }

    ?investor wm:investorId ?investorId ;
              wm:investorName ?investorName .
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
