SELECT DISTINCT ?holdingId ?investmentName
WHERE {
  ?holding rdf:type wm:PortfolioHolding ;
           wm:holdingId ?holdingId .
  OPTIONAL { ?holding wm:investmentName ?investmentName . }
  FILTER NOT EXISTS {
    ?holding wm:hasSector ?sector .
    ?sector rdf:type wm:Sector .
  }
}

PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?action
WHERE {
    ?actionNode rdf:type wm:RebalancingAction ;
                wm:rebalanceId "0000aba5-8fe8-4dcf-b422-fd78608ffddb" ;
                wm:logic ?logic ;
                wm:action ?action .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow) (?riskScore AS ?risk_score)
WHERE {
    {
        SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasCashFlow ?cashFlow .
            ?cashFlow wm:amount ?amountRaw .
            BIND(xsd:decimal(?amountRaw) AS ?amount)
        }
        GROUP BY ?investor ?investorId
    }

    ?investor wm:investorName ?investorName ;
              wm:hasPortfolioHealth ?health .

    ?health wm:riskScore ?riskScoreRaw .
    BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore)

    FILTER(?netCashFlow < 0 && ?riskScore > 70)
}
GROUP BY ?investor ?investorName ?investorId ?riskScore
ORDER BY ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .

    FILTER EXISTS {
        ?rebalancingAction rdf:type wm:RebalancingAction ;
                           wm:rebalancingActionOfInvestor ?investor ;
                           wm:action ?action .
        FILTER(LCASE(STR(?action)) = "manual override")
    }

    FILTER EXISTS {
        ?scenarioRebalancing rdf:type wm:ScenarioRebalancing ;
                             wm:scenarioRebalancingOfInvestor ?investor ;
                             wm:scenario ?scenario .
        FILTER(LCASE(STR(?scenario)) = "flash crash")
    }
}

PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?health .

  ?health rdf:type wm:PortfolioHealth ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore .

  FILTER(xsd:decimal(?riskScore) > 70) .
  FILTER(xsd:decimal(?liquidityScore) < 30) .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor
           (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
           (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
           (AVG(xsd:decimal(?diversificationScore)) AS ?avgDiversificationScore)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?goal ;
                wm:hasSectorAllocation ?allocation ;
                wm:hasPortfolioHealth ?health .
      ?goal wm:progressPct ?progressPct .
      ?allocation wm:allocationPct ?allocationPct .
      ?health wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investor
  }
  FILTER(?avgProgressPct < 25 && ?avgAllocationPct > 40 && ?avgDiversificationScore < 30)
  ?investor wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasScenarioRebalancing ?scenarioRebalancing .

  ?cashFlow rdf:type wm:CashFlow ;
            wm:type "Deposit" .

  ?scenarioRebalancing rdf:type wm:ScenarioRebalancing ;
                       wm:hasMarketScenario ?marketScenario .

  ?marketScenario rdf:type wm:MarketScenario ;
                  wm:scenario ?scenarioRaw .
  BIND(LCASE(STR(?scenarioRaw)) AS ?scenario)
  FILTER(CONTAINS(?scenario, "economic growth"))
}
GROUP BY ?investorId ?investorName

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investorId (SAMPLE(?investorNameRaw) AS ?investorName)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:segment "Moderate" ;
                      wm:investorId ?investorId ;
                      wm:hasPortfolioHealth ?health .
            ?health rdf:type wm:PortfolioHealth ;
                    wm:riskScore ?riskScore ;
                    wm:liquidityScore ?liquidityScore .
            FILTER(xsd:decimal(?riskScore) > 75) .
            FILTER(xsd:decimal(?liquidityScore) < 25) .
            OPTIONAL { ?investor wm:investorName ?investorNameRaw . }
        }
        GROUP BY ?investorId
    }
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName ?sector ?segment ?category ?returnsPct
WHERE {
    ?holding rdf:type wm:PortfolioHolding ;
             wm:holdingId ?holdingId ;
             wm:investmentName ?investmentName ;
             wm:returnsPct ?returnsPctRaw .

    BIND(xsd:decimal(?returnsPctRaw) AS ?returnsPct)
    FILTER(?returnsPct < -20)

    OPTIONAL { ?holding wm:sector ?sector }
    OPTIONAL { ?holding wm:segment ?segment }
    OPTIONAL { ?holding wm:category ?category }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:segment "Conservative" ;
              wm:investorName ?investorName ;
              wm:hasPortfolioHealth ?health .

    ?health rdf:type wm:PortfolioHealth ;
            wm:riskScore ?riskScore ;
            wm:liquidityScore ?liquidityScore .

    FILTER(xsd:decimal(?riskScore) > 80) .
    FILTER(xsd:decimal(?liquidityScore) < 20) .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
           (AVG(xsd:decimal(?avgSharpeRatio)) AS ?avgSharpe)
           (MAX(xsd:decimal(?riskScore)) AS ?maxRiskScore)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:progressPct ?progressPct ;
            wm:avgSharpeRatio ?avgSharpeRatio ;
            wm:belongsToInvestor ?investor .
      ?investor wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?health .
      ?health rdf:type wm:PortfolioHealth ;
              wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
  FILTER(?avgProgressPct < 40 && ?avgSharpe < 0 && ?maxRiskScore > 70)

  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor (COUNT(?holding) AS ?holdingCount) (COUNT(?sectorHolding) AS ?sectorCount) (COUNT(?segmentHolding) AS ?segmentCount) (COUNT(?categoryHolding) AS ?categoryCount) (COUNT(?investmentTypeHolding) AS ?investmentTypeCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:investorName ?investorName .
      ?investor wm:hasSegment ?segment .
      ?investor wm:hasRiskTolerance ?riskTolerance .
      ?investor wm:hasTimeHorizon ?timeHorizon .
      ?investor wm:hasInvestmentGoal ?investmentGoal .

      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      OPTIONAL { ?holding wm:hasSector ?sectorHolding . }
      OPTIONAL { ?holding wm:hasSegment ?segmentHolding . }
      OPTIONAL { ?holding wm:hasCategory ?categoryHolding . }
      OPTIONAL { ?holding wm:hasInvestmentType ?investmentTypeHolding . }
    }
    GROUP BY ?investor ?investorId ?investorName
  }
  FILTER(?holdingCount > 0 && (?sectorCount = 0 || ?segmentCount = 0 || ?categoryCount = 0 || ?investmentTypeCount = 0))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  ?riskTolerance
  (SUM(xsd:decimal(?netCashFlow)) AS ?net_cash_flow)
  (AVG(xsd:decimal(?progressPct)) AS ?average_goal_progress_pct)
WHERE {
  {
    SELECT
      ?investorId
      (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT
      ?investorId
      (AVG(xsd:decimal(?progressPctRaw)) AS ?progressPct)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPctRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance

PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?targetAmount ?currentValue
WHERE {
    ?goal rdf:type wm:InvestmentGoal ;
          wm:goalId "0006aef2-ab21-43d6-8885-4730e21c870b" ;
          wm:targetAmount ?targetAmountRaw ;
          wm:currentValue ?currentValueRaw .

    BIND(xsd:decimal(?targetAmountRaw) AS ?targetAmount)
    BIND(xsd:decimal(?currentValueRaw) AS ?currentValue)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?dividendAmount)) AS ?totalDividends)
WHERE {
  {
    SELECT ?investor ?investorId (SUM(xsd:decimal(?amount)) AS ?dividendAmount)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId .

      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type ?cashFlowTypeRaw .

      FILTER(LCASE(STR(?cashFlowTypeRaw)) = "dividend")
    }
    GROUP BY ?investor ?investorId
  }

  ?investor wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?totalDividends) LIMIT 10

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (AVG(xsd:decimal(?preAggregatedRiskScore)) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investorId ?categoryValue (AVG(xsd:decimal(?riskScore)) AS ?preAggregatedRiskScore)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCategory ?categoryObj ;
                wm:hasPortfolioHealth ?health .
      ?categoryObj rdf:type wm:Category .
      OPTIONAL { ?categoryObj wm:category ?categoryValue . }
      ?health wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId ?categoryValue
  }
  BIND(COALESCE(?categoryValue, "NULL") AS ?category)
}
GROUP BY ?category

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId .
    OPTIONAL { ?investor wm:investorName ?investorName . }
    FILTER NOT EXISTS {
        ?investor rdf:type wm:Investor .
        { ?investor wm:timeHorizon ?timeHorizon . }
        UNION
        { ?investor wm:hasTimeHorizon ?timeHorizonObj .
          ?timeHorizonObj wm:timeHorizon ?timeHorizon . }
    }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:riskTolerance "Conservative" .

      ?holding wm:heldByInvestor ?investor ;
               wm:hasInvestmentType ?investmentType .

      ?investmentType rdfs:label ?investmentTypeLabel .
      FILTER(LCASE(STR(?investmentTypeLabel)) = "venture capital")
    }
    GROUP BY ?investorId
  }

  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    (COALESCE(?riskToleranceLabel, "NULL") AS ?riskToleranceGroup)
    (COALESCE(?rebalancingLogicLabel, "NULL") AS ?rebalancingLogic)
    (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
    {
        SELECT ?investor ?investorId ?riskToleranceLabel ?rebalancingLogicLabel
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId .

            FILTER EXISTS {
                ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
            }

            OPTIONAL {
                ?investor wm:hasRiskTolerance ?riskTolerance .
                ?riskTolerance rdfs:label ?riskToleranceLabel .
            }

            OPTIONAL {
                ?investor wm:hasRebalancingAction ?rebalancingAction .
                ?rebalancingAction wm:usesRebalancingLogic ?rebalancingLogicObj .
                ?rebalancingLogicObj rdfs:label ?rebalancingLogicLabel .
            }
        }
        GROUP BY ?investor ?investorId ?riskToleranceLabel ?rebalancingLogicLabel
    }
}
GROUP BY ?riskToleranceLabel ?rebalancingLogicLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(xsd:decimal(?depositAmount)) AS ?deposit_amount)
       (SUM(xsd:decimal(?withdrawalAmount)) AS ?withdrawal_amount)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?depositAmount)
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type "Deposit" .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) * -1 AS ?withdrawalAmount)
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type "Withdrawal" .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId ;
            wm:category ?categoryRaw .
  BIND(COALESCE(STR(?categoryRaw), "NULL") AS ?category)
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
