    ?goal rdf:type wm:InvestmentGoal ;
          wm:investmentGoal ?goalTypeRaw .
    FILTER(LCASE(STR(?goalTypeRaw)) = "emergency fund") .

    ?investor wm:hasPortfolioHealth ?health .
    ?health rdf:type wm:PortfolioHealth ;
            wm:liquidityScore ?liquidityScoreRaw .
    FILTER(xsd:decimal(?liquidityScoreRaw) > 70) .

    ?investor wm:hasCashFlow ?cashFlow .
    ?cashFlow rdf:type wm:CashFlow ;
              wm:type ?cashFlowTypeRaw .
    FILTER(LCASE(STR(?cashFlowTypeRaw)) = "withdrawal") .
}

