PREFIX kg: <https://wealth.example.org/kg/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?category
    ?source
    (SUM(xsd:decimal(?amount)) AS ?totalAmount)
WHERE {
    {
        SELECT
            ?investor
            ?cashFlowSource
            (SUM(xsd:decimal(?amountRaw)) AS ?amount)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:hasCashFlowSource ?cashFlowSource ;
                      wm:amount ?amountRaw .
        }
        GROUP BY ?investor ?cashFlowSource
    }
    ?investor rdf:type wm:Investor ;
              wm:hasCategory ?categoryObj .
    ?categoryObj rdfs:label ?category .

    ?cashFlowSource rdfs:label ?source .
}
GROUP BY ?category ?source

