}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor (MIN(?invId) AS ?investorId) (MIN(?invName) AS ?investorName)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?invId ;
                wm:investorName ?invName .

      {
        SELECT ?investor
        WHERE {
          ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
          ?scenarioRebalancing wm:scenario "Bear Market" .
        }
        GROUP BY ?investor
      }

      {
        SELECT ?investor
        WHERE {
          ?investor wm:hasCashFlow ?cashFlow .
          ?cashFlow wm:type "Withdrawal" .
        }
        GROUP BY ?investor
      }
    }
    GROUP BY ?investor
  }
  BIND(?investorId AS ?investorIdFinal)
  BIND(?investorName AS ?investorNameFinal)
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?segment_representation
    (COUNT(DISTINCT ?investor_with_holding) AS ?investor_count_with_holding)
    (COUNT(DISTINCT ?investor_without_holding) AS ?investor_count_without_holding)
WHERE {
    {
        SELECT ?investor_id ?segment_representation
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investor_id ;
                      wm:hasSegment ?segment .
            OPTIONAL { ?segment rdfs:label ?segment_label . }
            BIND(COALESCE(?segment_label, "NULL") AS ?segment_representation)
        }
    }
    {
        SELECT ?investor_id ?segment_representation (1 AS ?has_matching_holding)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investor_id ;
                      wm:hasSegment ?segment .
            OPTIONAL { ?segment rdfs:label ?segment_label . }
            BIND(COALESCE(?segment_label, "NULL") AS ?segment_representation)

            ?holding rdf:type wm:PortfolioHolding ;
                     wm:heldByInvestor ?investor ;
                     wm:hasSegment ?holding_segment .
            OPTIONAL { ?holding_segment rdfs:label ?holding_segment_label . }
            FILTER(COALESCE(?holding_segment_label, "NULL") = ?segment_representation)
        }
        GROUP BY ?investor_id ?segment_representation
    }
    BIND(IF(BOUND(?has_matching_holding), ?investor_id, ?UNDEF) AS ?investor_with_holding)
    BIND(IF(!BOUND(?has_matching_holding), ?investor_id, ?UNDEF) AS ?investor_without_holding)
}
GROUP BY ?segment_representation

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?shortfall)) - SUM(xsd:decimal(?holdingGain)) - SUM(xsd:decimal(?netCashFlow)) + SUM(xsd:decimal(?riskScore)) AS ?quantitativeBurdenScore)
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .

    {
        SELECT ?investor (SUM(xsd:decimal(?shortfallRaw)) AS ?shortfall)
        WHERE {
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:shortfall ?shortfallRaw .
        }
        GROUP BY ?investor
    }

    {
        SELECT ?investor (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?holdingGain)
        WHERE {
            ?holding rdf:type wm:PortfolioHolding ;
                     wm:heldByInvestor ?investor ;
                     wm:currentValue ?currentValue ;
                     wm:cost ?cost .
        }
        GROUP BY ?investor
    }

    {
        SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:amount ?amount .
        }
        GROUP BY ?investor
    }

    {
        SELECT ?investor (SUM(xsd:decimal(?riskScoreRaw)) AS ?riskScore)
        WHERE {
            ?health rdf:type wm:PortfolioHealth ;
                    wm:healthOfInvestor ?investor ;
                    wm:riskScore ?riskScoreRaw .
        }
        GROUP BY ?investor
    }
}
GROUP BY ?investorId ?investorName
HAVING (SUM(xsd:decimal(?shortfall)) - SUM(xsd:decimal(?holdingGain)) - SUM(xsd:decimal(?netCashFlow)) + SUM(xsd:decimal(?riskScore)) > 50000000)
ORDER BY DESC(?quantitativeBurdenScore)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investor (COUNT(?holding) AS ?negativeHoldingCount)
        WHERE {
            ?investor a wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:category "Debt" ;
                      wm:hasHolding ?holding .
            ?holding wm:returnsPct ?returnsPctRaw .
            FILTER(xsd:decimal(?returnsPctRaw) < 0)
        }
        GROUP BY ?investor
        HAVING(COUNT(?holding) > 0)
    }
    ?investor wm:investorName ?investorName ;
              wm:hasPortfolioHealth ?health .
    ?health wm:diversificationScore ?diversificationScoreRaw .
    FILTER(xsd:decimal(?diversificationScoreRaw) < 35)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(?scoreComponent) AS ?temporalPressureScore)
WHERE {
  {
    SELECT ?investor
           (COALESCE(?netCashFlow2025Val, 0) + COALESCE(?rebalanceAmountVal, 0) - COALESCE(?goalShortfallVal, 0) + COALESCE(?scenarioAllocationChangeVal, 0) AS ?scoreComponent)
    WHERE {
      {
        SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow2025Val)
        WHERE {
          ?investor rdf:type wm:Investor ;
                    wm:investorId ?investorId .
          ?investor wm:hasCashFlow ?cashFlow .
          ?cashFlow wm:date ?date ;
                    wm:amount ?amount .
          FILTER(STRSTARTS(STR(?date), "2025"))
        }
        GROUP BY ?investor
      }

      {
        SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?rebalanceAmountVal)
        WHERE {
          ?investor rdf:type wm:Investor ;
                    wm:investorId ?investorId .
          ?investor wm:hasRebalancingAction ?rebalancingAction .
          ?rebalancingAction wm:amount ?amount .
        }
        GROUP BY ?investor
      }

      {
        SELECT ?investor (SUM(xsd:decimal(?shortfall)) AS ?goalShortfallVal)
        WHERE {
          ?investor rdf:type wm:Investor ;
                    wm:investorId ?investorId .
          ?investor wm:hasInvestmentGoal ?goal .
          ?goal wm:shortfall ?shortfall .
        }
        GROUP BY ?investor
      }

      {
        SELECT ?investor (SUM(ABS(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct))) AS ?scenarioAllocationChangeVal)
        WHERE {
          ?investor rdf:type wm:Investor ;
                    wm:investorId ?investorId .
          ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
          ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct ;
                              wm:currentAllocationPct ?currentAllocationPct .
        }
        GROUP BY ?investor
      }
    }
  }

  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?temporalPressureScore) ASC(?investorId)
LIMIT 10

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic (COUNT(?preCount) AS ?actionCount)
WHERE {
  {
    SELECT ?logicUri (COUNT(DISTINCT ?action) AS ?preCount)
    WHERE {
      ?action rdf:type wm:RebalancingAction .
      ?action wm:hasRebalancingLogic ?logicUri .
      ?logicUri rdf:type wm:RebalancingLogic .
    }
    GROUP BY ?logicUri
  }
  OPTIONAL { ?logicUri rdfs:label ?logicLabel . }
  BIND(COALESCE(?logicLabel, STR(?logicUri)) AS ?logic)
}
GROUP BY ?logic

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investorId ?investorName
           (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
           (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
           (MAX(xsd:decimal(?riskScore)) AS ?maxRiskScore)
           (MAX(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?maxScenarioChange)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:investorName ?investorName .

      OPTIONAL {
        ?investor wm:hasCashFlow ?cashFlow .
        ?cashFlow wm:amount ?amount .
      }

      OPTIONAL {
        ?investor wm:hasInvestmentGoal ?goal .
        ?goal wm:progressPct ?progressPct .
      }

      OPTIONAL {
        ?investor wm:hasPortfolioHealth ?health .
        ?health wm:riskScore ?riskScore .
      }

      OPTIONAL {
        ?investor wm:hasScenarioRebalancing ?scenario .
        ?scenario wm:newAllocationPct ?newAllocationPct ;
                  wm:currentAllocationPct ?currentAllocationPct .
      }
    }
    GROUP BY ?investorId ?investorName
  }

  FILTER(?totalCashFlow > 100000000)
  FILTER(?avgProgressPct < 25)
  FILTER(?maxRiskScore > 70)
  FILTER(?maxScenarioChange > 20)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector
       (AVG(?avgProgress) AS ?avgGoalProgress)
       (AVG(?avgLiquidity) AS ?avgLiquidityScore)
WHERE {
    {
        SELECT ?investorId ?sector
               (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
               (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidity)
        WHERE {
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:progressPct ?progressPct ;
                  wm:belongsToInvestor ?investor .
            ?health rdf:type wm:PortfolioHealth ;
                    wm:liquidityScore ?liquidityScore ;
                    wm:healthOfInvestor ?investor .
            ?investor wm:investorId ?investorId .
            {
                ?holding rdf:type wm:PortfolioHolding ;
                         wm:heldByInvestor ?investor ;
                         wm:sector ?sector .
            }
            UNION
            {
                ?allocation rdf:type wm:SectorAllocation ;
                            wm:allocationOfInvestor ?investor ;
                            wm:sector ?sector .
            }
        }
        GROUP BY ?investorId ?sector
    }
}
GROUP BY ?sector

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasSectorAllocation ?sectorAlloc .
      ?sectorAlloc rdf:type wm:SectorAllocation ;
                   wm:sector "Technology" ;
                   wm:allocationPct ?allocPctRaw .
      FILTER(xsd:decimal(?allocPctRaw) > 30)

      ?investor wm:hasHolding ?holding .
      ?holding rdf:type wm:PortfolioHolding ;
               wm:sector "Technology" .
    }
    GROUP BY ?investorId
  }

  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceValue (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor ?riskToleranceValue
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:hasPortfolioHealth ?portfolioHealth ;
                wm:riskTolerance ?riskToleranceValue .
      ?portfolioHealth wm:riskScore ?riskScore .
      FILTER(xsd:decimal(?riskScore) > 70)
    }
    GROUP BY ?investor ?riskToleranceValue
  }
}
GROUP BY ?riskToleranceValue

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?holdingId
WHERE {
  ?holding rdf:type wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:heldByInvestor ?investor .
  ?investor wm:investorId ?investorId .
  FILTER NOT EXISTS {
    ?holding wm:segment ?segment .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?timeHorizon
    (AVG(?preRiskScore) AS ?avgRiskScore)
    (AVG(?preLiquidityScore) AS ?avgLiquidityScore)
    (AVG(?preDiversificationScore) AS ?avgDiversificationScore)
WHERE {
    {
        SELECT
            ?investorId
            (COALESCE(?timeHorizonRaw, "NULL") AS ?timeHorizon)
            (AVG(xsd:decimal(?riskScore)) AS ?preRiskScore)
            (AVG(xsd:decimal(?liquidityScore)) AS ?preLiquidityScore)
            (AVG(xsd:decimal(?diversificationScore)) AS ?preDiversificationScore)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasPortfolioHealth ?portfolioHealth .
            OPTIONAL { ?investor wm:hasTimeHorizon ?timeHorizonNode .
                       ?timeHorizonNode rdfs:label ?timeHorizonRaw . }

            ?portfolioHealth rdf:type wm:PortfolioHealth ;
                            wm:riskScore ?riskScore ;
                            wm:liquidityScore ?liquidityScore ;
                            wm:diversificationScore ?diversificationScore .
        }
        GROUP BY ?investorId ?timeHorizonRaw
    }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
