PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .

    {
        SELECT ?investor (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
        WHERE {
            ?investor wm:hasInvestmentGoal ?goal .
            ?goal wm:shortfall ?shortfall .
        }
        GROUP BY ?investor
    }
    FILTER(xsd:decimal(?totalShortfall) > 0) .

    {
        SELECT ?investor (SUM(xsd:decimal(?currentValue)) - SUM(xsd:decimal(?cost)) AS ?totalHoldingGain)
        WHERE {
            ?investor wm:hasHolding ?holding .
            ?holding wm:currentValue ?currentValue ;
                     wm:cost ?cost .
        }
        GROUP BY ?investor
    }
    FILTER(xsd:decimal(?totalHoldingGain) < 0) .

    {
        SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
        WHERE {
            ?investor wm:hasCashFlow ?cashFlow .
            ?cashFlow wm:amount ?amount .
        }
        GROUP BY ?investor
    }
    FILTER(xsd:decimal(?totalCashFlow) < 10000) .

    {
        SELECT ?investor (MAX(xsd:decimal(?riskScore)) AS ?maxRiskScore)
        WHERE {
            ?investor wm:hasPortfolioHealth ?health .
            ?health wm:riskScore ?riskScore .
        }
        GROUP BY ?investor
    }
    FILTER(xsd:decimal(?maxRiskScore) > 65) .
}

