SELECT ?investorName ?allocationPct ?riskScore
WHERE {
  {
    SELECT ?investor (MAX(?allocPctRaw) AS ?allocationPct) (MAX(?riskScoreRaw) AS ?riskScore)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:hasSectorAllocation ?sectorAlloc ;
                wm:hasPortfolioHealth ?health .
      ?sectorAlloc rdf:type wm:SectorAllocation ;
                   wm:allocationPct ?allocPctRaw .
      ?health rdf:type wm:PortfolioHealth ;
              wm:riskScore ?riskScoreRaw .
    }
    GROUP BY ?investor
  }
  FILTER(xsd:decimal(?allocationPct) > 40 && xsd:decimal(?riskScore) > 75)
  ?investor wm:investorName ?investorName .
}

