PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investorId
               (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalHoldingGain)
        WHERE {
            ?holding rdf:type wm:PortfolioHolding ;
                     wm:heldByInvestor ?investor ;
                     wm:currentValue ?currentValue ;
                     wm:cost ?cost .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId
               (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:amount ?amount .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId ?investorName
               (AVG(xsd:decimal(?avgSharpeRatio)) AS ?avgSharpeRatioAvg)
               (AVG(xsd:decimal(?avgVolatilityPct)) AS ?avgVolatilityPctAvg)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:investorName ?investorName .
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:avgSharpeRatio ?avgSharpeRatio ;
                  wm:avgVolatilityPct ?avgVolatilityPct .
        }
        GROUP BY ?investorId ?investorName
    }
    FILTER (?avgSharpeRatioAvg < 0 &&
            ?avgVolatilityPctAvg > 10 &&
            ?totalHoldingGain < 0 &&
            ?netCashFlow < 1000000)
}

