                      wm:investorId ?investorId ;
                      wm:hasHolding ?holding .
            ?holding wm:returnsPct ?returnsPctRaw .
            FILTER(xsd:decimal(?returnsPctRaw) < 0)
        }
        GROUP BY ?investorId
    }

    {
        SELECT ?investorId WHERE {
            ?investor a wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasSectorAllocation ?allocation .
            ?allocation wm:allocationPct ?allocationPctRaw .
            FILTER(xsd:decimal(?allocationPctRaw) > 30)
        }
        GROUP BY ?investorId
    }

    {
        SELECT ?investorId WHERE {
            ?investor a wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasPortfolioHealth ?health .
            ?health wm:liquidityScore ?liquidityScoreRaw .
            FILTER(xsd:decimal(?liquidityScoreRaw) < 30)
        }
