PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskTolerance
    (AVG(xsd:decimal(?shortfallSum)) AS ?avgGoalShortfall)
    (AVG(xsd:decimal(?portfolioHealthScore)) AS ?avgPortfolioHealthScore)
WHERE {
    {
        SELECT
            ?investorId
            (COALESCE(?riskToleranceValue, "NULL") AS ?riskTolerance)
            (SUM(xsd:decimal(?shortfall)) AS ?shortfallSum)
            (AVG(?portfolioHealthScoreRaw) AS ?portfolioHealthScore)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasRiskTolerance ?riskToleranceNode .
            OPTIONAL { ?riskToleranceNode wm:riskTolerance ?riskToleranceValue . }

            ?investor wm:hasInvestmentGoal ?goal .
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:shortfall ?shortfall .

            ?investor wm:hasPortfolioHealth ?health .
            ?health rdf:type wm:PortfolioHealth ;
                    wm:diversificationScore ?diversificationScore ;
                    wm:liquidityScore ?liquidityScore ;
                    wm:riskScore ?riskScore ;
                    wm:goalMatchPct ?goalMatchPct .

            BIND(
                (xsd:decimal(?diversificationScore) + xsd:decimal(?liquidityScore) +
                 xsd:decimal(?riskScore) + xsd:decimal(?goalMatchPct)) / 4
                AS ?portfolioHealthScoreRaw
            )
        }
        GROUP BY ?investorId ?riskToleranceValue
    }
}
GROUP BY ?riskTolerance

