PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investor
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId .

            {
                SELECT ?investor (SUM(xsd:decimal(?holdingGain)) AS ?totalHoldingGain)
                WHERE {
                    ?investor wm:hasHolding ?holding .
                    ?holding wm:currentValue ?currentValue ;
                             wm:cost ?cost .
                    BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?holdingGain)
                }
                GROUP BY ?investor
                HAVING (SUM(xsd:decimal(?holdingGain)) < 0)
            }

            {
                SELECT ?investor (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
                WHERE {
                    ?investor wm:hasInvestmentGoal ?goal .
                    ?goal wm:shortfall ?shortfall .
                }
                GROUP BY ?investor
                HAVING (SUM(xsd:decimal(?shortfall)) > 0)
            }

            {
                SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
                WHERE {
                    ?investor wm:hasCashFlow ?cashFlow .
                    ?cashFlow wm:amount ?amount .
                }
                GROUP BY ?investor
                HAVING (SUM(xsd:decimal(?amount)) < 0)
            }
        }
        GROUP BY ?investor
    }

    ?investor wm:investorId ?investorId ;
              wm:investorName ?investorName .
}

