SELECT
    ?riskToleranceLabel
    ?sector
    (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
    {
        SELECT ?investorId ?riskToleranceLabel ?sector
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasRiskTolerance ?riskTolerance ;
                      wm:hasPortfolioHealth ?portfolioHealth .

            ?riskTolerance rdfs:label ?riskToleranceLabel .

            ?portfolioHealth wm:diversificationScore ?diversificationScoreRaw .
            FILTER(xsd:decimal(?diversificationScoreRaw) < 30) .

            ?investor wm:hasSectorAllocation ?sectorAllocation .
            ?sectorAllocation wm:sector ?sector ;
                             wm:allocationPct ?allocationPctRaw .
            FILTER(xsd:decimal(?allocationPctRaw) > 30) .
        }
        GROUP BY ?investorId ?riskToleranceLabel ?sector
        HAVING(COUNT(?sectorAllocation) > 0)
    }
}
GROUP BY ?riskToleranceLabel ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?shortfall)) - SUM(xsd:decimal(?holdingGain)) - SUM(xsd:decimal(?netCashFlow)) + SUM(xsd:decimal(?riskPressureScore)) AS ?score)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?shortfallRaw)) AS ?shortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfallRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?currentValueRaw) - xsd:decimal(?costRaw)) AS ?holdingGain)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValueRaw ;
               wm:cost ?costRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?amountRaw)) AS ?netCashFlow)
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?riskScoreRaw)) AS ?riskPressureScore)
    WHERE {
      ?health rdf:type wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScoreRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investor
  }

  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor
    WHERE {
      ?investor rdf:type wm:Investor .
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:date ?dateRaw .
      BIND(xsd:date(?dateRaw) AS ?date)
      FILTER(?date > "2026-04-28"^^xsd:date)
    }
    GROUP BY ?investor
    HAVING(COUNT(?cashFlow) > 0)
  }
  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName .
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
