SELECT DISTINCT ?investor ?investorId
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId .
  FILTER NOT EXISTS {
    ?goal rdf:type wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:investmentGoal ?investmentGoalRaw .
    BIND(LCASE(STR(?investmentGoalRaw)) AS ?investmentGoal)
    FILTER(?investmentGoal IN (
      "retirement planning",
      "growth",
      "income generation",
      "wealth preservation",
      "child education",
      "emergency fund"
    ))
  }
}

