PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cashFlowTypeLabel (COUNT(DISTINCT ?preAggInvestor) AS ?investorCount)
WHERE {
    {
        SELECT ?cashFlowType ?investor
        WHERE {
            ?cashFlow a wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:hasCashFlowType ?cashFlowType .
            ?investor a wm:Investor .
        }
        GROUP BY ?cashFlowType ?investor
    }
    ?cashFlowType rdfs:label ?cashFlowTypeLabel .
    BIND(?investor AS ?preAggInvestor)
}
GROUP BY ?cashFlowTypeLabel

