PREFIX kg: <https://wealth.example.org/kg/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    (AVG(xsd:decimal(?riskScore)) AS ?average_risk_score)
    (AVG(xsd:decimal(?liquidityScore)) AS ?average_liquidity_score)
    (AVG(xsd:decimal(?diversificationScore)) AS ?average_diversification_score)
    (AVG(xsd:decimal(?goalMatchPct)) AS ?average_goal_match_pct)
WHERE {
    ?portfolioHealth rdf:type wm:PortfolioHealth ;
                    wm:riskScore ?riskScore ;
                    wm:liquidityScore ?liquidityScore ;
                    wm:diversificationScore ?diversificationScore ;
                    wm:goalMatchPct ?goalMatchPct .
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal rdf:type wm:InvestmentGoal ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  FILTER(xsd:decimal(?avgProgress) < 30) .

  {
    SELECT ?investor (xsd:decimal(?riskScore) AS ?risk)
    WHERE {
      ?investor wm:hasPortfolioHealth ?health .
      ?health rdf:type wm:PortfolioHealth ;
              wm:riskScore ?riskScore .
    }
  }
  FILTER(xsd:decimal(?risk) > 60) .

  {
    SELECT ?investor
           (SUM(IF(LCASE(STR(?type)) = "withdrawal", xsd:decimal(?amount), 0)) AS ?totalWithdrawal)
           (SUM(IF(LCASE(STR(?type)) = "deposit", xsd:decimal(?amount), 0)) AS ?totalDeposit)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow rdf:type wm:CashFlow ;
                wm:type ?type ;
                wm:amount ?amount .
    }
    GROUP BY ?investor
  }
  FILTER(xsd:decimal(?totalWithdrawal) > xsd:decimal(?totalDeposit)) .

  FILTER EXISTS {
    ?investor wm:hasRebalancingAction ?action .
    ?action rdf:type wm:RebalancingAction ;
            wm:action ?actionType .
    FILTER(LCASE(STR(?actionType)) = "sell")
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor (MIN(?investorIdRaw) AS ?investorId)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorIdRaw .
      OPTIONAL { ?investor wm:investorName ?investorNameRaw . }

      # Has PortfolioHealth
      ?investor wm:hasPortfolioHealth ?health .
      ?health rdf:type wm:PortfolioHealth .

      # Has PortfolioHolding
      ?investor wm:hasHolding ?holding .
      ?holding rdf:type wm:PortfolioHolding .

      # Missing RiskTolerance context
      FILTER NOT EXISTS {
        ?investor wm:hasRiskTolerance ?riskTolerance .
        ?riskTolerance rdf:type wm:RiskTolerance .
      }
    }
    GROUP BY ?investor
  }
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
