        }
        GROUP BY ?investor ?investorId
    }
    {
        SELECT ?investor
        WHERE {
            ?investor wm:hasSectorAllocation ?allocation .
            ?allocation wm:sector "Pharma" ;
                        wm:allocationPct ?allocationPctRaw .
            FILTER(xsd:decimal(?allocationPctRaw) > 0)
        }
        GROUP BY ?investor
    }
    {
        SELECT ?investor
        WHERE {
            ?investor wm:hasHolding ?holding .
            ?holding wm:sector "Pharma" .
        }
        GROUP BY ?investor
    }
    ?investor wm:investorName ?investorName .
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName WHERE {
    {
        SELECT ?investorId
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasPortfolioHealth ?health .
            ?health rdf:type wm:PortfolioHealth ;
                    wm:goalMatchPct ?goalMatchPctRaw ;
                    wm:riskScore ?riskScoreRaw .
            FILTER(xsd:decimal(?goalMatchPctRaw) < 30)
            FILTER(xsd:decimal(?riskScoreRaw) > 70)

            ?holding rdf:type wm:PortfolioHolding ;
                     wm:heldByInvestor ?investor ;
                     wm:returnsPct ?returnsPctRaw .
            FILTER(xsd:decimal(?returnsPctRaw) < 0)

            ?allocation rdf:type wm:SectorAllocation ;
                        wm:allocationOfInvestor ?investor ;
                        wm:allocationPct ?allocationPctRaw .
            FILTER(xsd:decimal(?allocationPctRaw) > 30)
        }
        GROUP BY ?investorId
    }

    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .
}

PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investor) AS ?investor_count)
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId .

  FILTER NOT EXISTS {
    ?investor wm:investmentGoal ?investmentGoal .
    FILTER(?investmentGoal != "")
  }
  FILTER NOT EXISTS {
    ?investor wm:riskTolerance ?riskTolerance .
    FILTER(?riskTolerance != "")
  }
  FILTER NOT EXISTS {
    ?investor wm:timeHorizon ?timeHorizon .
    FILTER(?timeHorizon != "")
  }
  FILTER NOT EXISTS {
    ?investor wm:sectorFocus ?sectorFocus .
    FILTER(?sectorFocus != "")
  }
  FILTER NOT EXISTS {
    ?investor wm:segment ?segment .
    FILTER(?segment != "")
  }
  FILTER NOT EXISTS {
    ?investor wm:category ?category .
    FILTER(?category != "")
  }
}

PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    (COALESCE(?timeHorizon, "NULL") AS ?time_horizon)
    (SUM(?rebalancingAmount) AS ?totalRebalancingAmount)
    (SUM(?cashFlowAmount) AS ?totalCashFlow)
    (AVG(?goalProgressPct) AS ?avgGoalProgressPct)
    (SUM(?shortfall) AS ?totalShortfall)
    (COUNT(?scenarioRebalanceId) AS ?scenarioRebalancingCount)
WHERE {
    {
        SELECT
            ?investorId
            (COALESCE(?timeHorizonRaw, "NULL") AS ?timeHorizon)
            (SUM(xsd:decimal(?raAmount)) AS ?rebalancingAmount)
            (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
            (AVG(xsd:decimal(?igProgressPct)) AS ?goalProgressPct)
            (SUM(xsd:decimal(?igShortfall)) AS ?shortfall)
            (COUNT(?srId) AS ?scenarioRebalanceId)
        WHERE {
            {
                SELECT ?investorId ?timeHorizonRaw (SUM(xsd:decimal(?amount)) AS ?raAmount)
                WHERE {
                    ?rebalancingAction rdf:type wm:RebalancingAction ;
                                       wm:investorId ?investorId ;
                                       wm:amount ?amount .
                    OPTIONAL { ?rebalancingAction wm:notes ?raNotes . }
                    BIND(
                        COALESCE(
                            IF(CONTAINS(LCASE(STR(?raNotes)), "time_horizon"),
                               REGEX(STR(?raNotes), "time_horizon[:=]\\s*([^,;]+)", "i"), "NULL"),
                            "NULL"
                        ) AS ?timeHorizonRaw
                    )
                }
                GROUP BY ?investorId ?timeHorizonRaw
            }
            {
                SELECT ?investorId ?timeHorizonRaw (SUM(xsd:decimal(?amount)) AS ?cfAmount)
                WHERE {
                    ?cashFlow rdf:type wm:CashFlow ;
                              wm:investorId ?investorId ;
                              wm:amount ?amount .
                    OPTIONAL { ?cashFlow wm:date ?cfDate . }
                    BIND(
                        COALESCE(
                            IF(BOUND(?cfDate), SUBSTR(STR(?cfDate), 1, 7), "NULL"),
                            "NULL"
                        ) AS ?timeHorizonRaw
                    )
                }
                GROUP BY ?investorId ?timeHorizonRaw
            }
            {
                SELECT ?investorId ?timeHorizonRaw
                       (AVG(xsd:decimal(?progressPct)) AS ?igProgressPct)
                       (SUM(xsd:decimal(?shortfallVal)) AS ?igShortfall)
                WHERE {
                    ?goal rdf:type wm:InvestmentGoal ;
                          wm:investorId ?investorId ;
                          wm:progressPct ?progressPct ;
                          wm:shortfall ?shortfallVal .
                    OPTIONAL { ?goal wm:timeToGoalMonths ?igTimeToGoal . }
                    BIND(
                        COALESCE(
                            IF(BOUND(?igTimeToGoal), STR(?igTimeToGoal), "NULL"),
                            "NULL"
                        ) AS ?timeHorizonRaw
                    )
                }
                GROUP BY ?investorId ?timeHorizonRaw
            }
            {
                SELECT ?investorId ?timeHorizonRaw (COUNT(?scenarioRebalanceId) AS ?srId)
                WHERE {
                    ?scenarioRebalancing rdf:type wm:ScenarioRebalancing ;
                                         wm:investorId ?investorId ;
                                         wm:scenarioRebalanceId ?scenarioRebalanceId .
                    OPTIONAL { ?scenarioRebalancing wm:rationale ?srRationale . }
                    BIND(
                        COALESCE(
                            IF(CONTAINS(LCASE(STR(?srRationale)), "time_horizon"),
                               REGEX(STR(?srRationale), "time_horizon[:=]\\s*([^,;]+)", "i"), "NULL"),
                            "NULL"
                        ) AS ?timeHorizonRaw
                    )
                }
                GROUP BY ?investorId ?timeHorizonRaw
            }
        }
        GROUP BY ?investorId ?timeHorizonRaw
    }
}
GROUP BY ?timeHorizon

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (AVG(xsd:decimal(?diversificationScore)) AS ?avgDiversificationScore)
WHERE {
    {
        SELECT ?investorId (AVG(xsd:decimal(?diversificationScoreRaw)) AS ?diversificationScore)
        WHERE {
            ?health rdf:type wm:PortfolioHealth ;
                    wm:diversificationScore ?diversificationScoreRaw ;
                    wm:healthOfInvestor ?investor .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    ?holding rdf:type wm:PortfolioHolding ;
             wm:heldByInvestor ?investor ;
             wm:hasSector ?sectorNode .
    ?sectorNode wm:sector ?sector .
    ?investor wm:investorId ?investorId .
}
GROUP BY ?sector

PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_goal (COUNT(?goalId) AS ?count_of_goals)
WHERE {
  ?goal rdf:type wm:InvestmentGoal ;
        wm:goalId ?goalId ;
        wm:progressPct ?progressPct ;
        wm:investmentGoal ?investment_goal .
  FILTER(xsd:decimal(?progressPct) < 25)
}
GROUP BY ?investment_goal

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?goalContext (COUNT(DISTINCT ?investorId) AS ?underfundedInvestorCount)
WHERE {
  {
    SELECT ?investorId ?timeHorizon ?goalContext
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall ;
            wm:hasInvestmentGoalType ?goalType .
      FILTER(xsd:decimal(?shortfall) > 0) .

      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
