       (SUM(xsd:decimal(?taxesPaid)) AS ?totalTaxesPaid)
WHERE {
  {
    SELECT ?investorId ?category
           (SUM(COALESCE(xsd:decimal(?holdingDividends), 0)) AS ?dividends)
           (SUM(COALESCE(xsd:decimal(?holdingTaxesPaid), 0)) AS ?taxesPaid)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:category ?categoryRaw .
      BIND(COALESCE(?categoryRaw, "NULL") AS ?category)
      OPTIONAL {
        ?holding rdf:type wm:PortfolioHolding ;
                 wm:heldByInvestor ?investor ;
                 wm:dividends ?holdingDividendsRaw ;
                 wm:taxesPaid ?holdingTaxesPaidRaw .
        BIND(COALESCE(xsd:decimal(?holdingDividendsRaw), 0) AS ?holdingDividends)
        BIND(COALESCE(xsd:decimal(?holdingTaxesPaidRaw), 0) AS ?holdingTaxesPaid)
      }
    }
    GROUP BY ?investorId ?category
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskTolerance
    (SUM(?cashFlowAmount) AS ?totalCashFlow)
    (AVG(?rebalancingAmount) AS ?avgRebalancingAmount)
    (SUM(?scenarioCount) AS ?totalScenarioChanges)
    (AVG(?riskScoreValue) AS ?avgRiskScore)
    (AVG(?goalMatchValue) AS ?avgGoalMatchPct)
WHERE {
    {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:amount ?amount .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId (AVG(xsd:decimal(?amount)) AS ?rebalancingAmount)
        WHERE {
            ?rebalancingAction rdf:type wm:RebalancingAction ;
                               wm:rebalancingActionOfInvestor ?investor ;
                               wm:amount ?amount .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId (COUNT(DISTINCT ?scenario) AS ?scenarioCount)
        WHERE {
            ?scenarioRebalancing rdf:type wm:ScenarioRebalancing ;
                                 wm:scenarioRebalancingOfInvestor ?investor ;
                                 wm:scenario ?scenario .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?riskScoreValue)
        WHERE {
            ?portfolioHealth rdf:type wm:PortfolioHealth ;
                             wm:healthOfInvestor ?investor ;
                             wm:riskScore ?riskScore .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId (AVG(xsd:decimal(?goalMatchPct)) AS ?goalMatchValue)
        WHERE {
            ?portfolioHealth rdf:type wm:PortfolioHealth ;
                             wm:healthOfInvestor ?investor ;
                             wm:goalMatchPct ?goalMatchPct .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:riskTolerance ?riskToleranceRaw .
    BIND(COALESCE(?riskToleranceRaw, "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?marketScenario (AVG(ABS(xsd:decimal(?allocationChange))) AS ?avgAbsAllocationChange)
WHERE {
  {
    SELECT ?marketScenario (xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct) AS ?allocationChange)
    WHERE {
      ?rebalancing rdf:type wm:ScenarioRebalancing ;
                   wm:hasMarketScenario ?marketScenario ;
                   wm:newAllocationPct ?newAllocationPct ;
                   wm:currentAllocationPct ?currentAllocationPct .
      ?marketScenario rdf:type wm:MarketScenario .
    }
  }
}
GROUP BY ?marketScenario
ORDER BY DESC(?avgAbsAllocationChange) LIMIT 5

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?category
    (SUM(?inflow) AS ?totalInflow)
    (SUM(?outflow) AS ?totalOutflow)
    (SUM(?shortfall) AS ?totalShortfall)
    (SUM(?dividends) AS ?totalDividends)
    (SUM(?taxesPaid) AS ?totalTaxesPaid)
WHERE {
    {
        SELECT
            ?investorId
            (COALESCE(?investorCategory, ?sectorCategory, "NULL") AS ?category)
            (SUM(COALESCE(?inflowAmount, 0)) AS ?inflow)
            (SUM(COALESCE(?outflowAmount, 0)) AS ?outflow)
            (SUM(COALESCE(?goalShortfall, 0)) AS ?shortfall)
            (SUM(COALESCE(?holdingDividends, 0)) AS ?dividends)
            (SUM(COALESCE(?holdingTaxesPaid, 0)) AS ?taxesPaid)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId .
            OPTIONAL { ?investor wm:category ?investorCategory . }

            OPTIONAL {
                ?investor wm:hasCashFlow ?cashFlow .
                ?cashFlow rdf:type wm:CashFlow ;
                          wm:amount ?amount ;
                          wm:type ?cashFlowType .
                BIND(IF(?cashFlowType = "Inflow", xsd:decimal(?amount), 0) AS ?inflowAmount)
                BIND(IF(?cashFlowType = "Outflow", xsd:decimal(?amount), 0) AS ?outflowAmount)
            }

            OPTIONAL {
                ?investor wm:hasInvestmentGoal ?goal .
                ?goal rdf:type wm:InvestmentGoal ;
                      wm:shortfall ?goalShortfall .
            }

            OPTIONAL {
                ?investor wm:hasHolding ?holding .
                ?holding rdf:type wm:PortfolioHolding ;
                         wm:dividends ?holdingDividends ;
                         wm:taxesPaid ?holdingTaxesPaid .
            }

            OPTIONAL {
                ?investor wm:hasSectorAllocation ?sectorAlloc .
                ?sectorAlloc rdf:type wm:SectorAllocation ;
                             wm:sector ?sectorCategory .
            }
        }
        GROUP BY ?investorId ?investorCategory ?sectorCategory
    }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?timeHorizon
    (SUM(?netAmount) AS ?totalNetAmount)
    (AVG(?progressPctDecimal) AS ?avgProgressPct)
    (SUM(?shortfallDecimal) AS ?totalShortfall)
WHERE {
    {
        SELECT
            ?investorId
            ?date
            ?timeHorizon
            (SUM(IF(LCASE(STR(?type)) = "inflow", xsd:decimal(?amount), xsd:decimal(?amount) * -1)) AS ?netAmount)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasCashFlow ?cashFlow ;
                      wm:timeHorizon ?timeHorizonRaw .

            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:amount ?amount ;
                      wm:date ?date ;
                      wm:type ?type .

            BIND(COALESCE(?timeHorizonRaw, "NULL") AS ?timeHorizon)
        }
        GROUP BY ?investorId ?date ?timeHorizon
    }
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal rdf:type wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct ;
          wm:shortfall ?shortfall .

    BIND(xsd:decimal(?progressPct) AS ?progressPctDecimal)
    BIND(xsd:decimal(?shortfall) AS ?shortfallDecimal)
}
GROUP BY ?timeHorizon

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?category
    (SUM(?totalCashFlow) AS ?totalCashFlowAmount)
    (SUM(?scenarioCount) AS ?scenarioChangeCount)
    (AVG(?avgAllocationPct) AS ?avgAllocationConcentration)
    (SUM(?sectorCount) AS ?sectorInvestmentCount)
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:category ?categoryRaw ;
              wm:investorId ?investorId .
    BIND(COALESCE(?categoryRaw, "NULL") AS ?category)

    {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:amount ?amount ;
                      wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }

    {
        SELECT ?investorId (COUNT(DISTINCT ?scenario) AS ?scenarioCount)
        WHERE {
            ?scenario rdf:type wm:ScenarioRebalancing ;
                      wm:scenarioRebalancingOfInvestor ?investor ;
                      wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }

    {
        SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
        WHERE {
            ?allocation rdf:type wm:SectorAllocation ;
                        wm:allocationOfInvestor ?investor ;
                        wm:allocationPct ?allocationPct ;
                        wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }

    {
        SELECT ?investorId (COUNT(DISTINCT ?sector) AS ?sectorCount)
        WHERE {
            ?holding rdf:type wm:PortfolioHolding ;
                     wm:heldByInvestor ?investor ;
                     wm:sector ?sector ;
                     wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
}
GROUP BY ?category

