SELECT ?sector ?riskScore_band (AVG(xsd:decimal(?returnsPct)) AS ?avg_returns_pct)
WHERE {
    {
        SELECT ?holdingId ?sector ?returnsPct
        WHERE {
            ?holding rdf:type wm:PortfolioHolding ;
                     wm:holdingId ?holdingId ;
                     wm:returnsPct ?returnsPct ;
                     wm:sector ?sector .
        }
    }
    {
        SELECT ?holdingId (FLOOR(xsd:decimal(?riskScore)/10) AS ?riskScore_band_raw)
        WHERE {
            ?health rdf:type wm:PortfolioHealth ;
                    wm:healthOfInvestor ?investor ;
                    wm:riskScore ?riskScore .
            ?holding rdf:type wm:PortfolioHolding ;
                     wm:heldByInvestor ?investor ;
                     wm:holdingId ?holdingId .
        }
    }
    BIND(COALESCE(STR(?riskScore_band_raw), "NULL") AS ?riskScore_band)
}
GROUP BY ?sector ?riskScore_band

