PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(DISTINCT ?investorId) AS ?distinctInvestorCount)
WHERE {
  {
    SELECT (SUBSTR(STR(?date), 1, 7) AS ?month) ?investorId
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:date ?date ;
                wm:cashFlowOfInvestor ?investor .
      ?investor wm:investorId ?investorId .
      FILTER(STRSTARTS(STR(?date), "2025"))
    }
    GROUP BY (SUBSTR(STR(?date), 1, 7) AS ?month) ?investorId
  }
}
GROUP BY ?month

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investorId
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasInvestmentGoal ?goal ;
                      wm:hasPortfolioHealth ?health ;
                      wm:hasCashFlow ?cashFlow ;
                      wm:hasRebalancingAction ?rebalanceAction .

            ?goal rdf:type wm:InvestmentGoal .
            {
                ?goal wm:shortfall ?shortfall .
                FILTER(xsd:decimal(?shortfall) > 0)
            } UNION {
                ?goal wm:progressPct ?progressPct .
                FILTER(xsd:decimal(?progressPct) < 100)
            }

            ?health rdf:type wm:PortfolioHealth ;
                    wm:liquidityScore ?liquidityScore .
            FILTER(xsd:decimal(?liquidityScore) < 30)

            ?cashFlow rdf:type wm:CashFlow ;
                      wm:type ?cashFlowType .
            FILTER(LCASE(STR(?cashFlowType)) = "withdrawal")

            ?rebalanceAction rdf:type wm:RebalancingAction ;
                             wm:action ?action .
            FILTER(LCASE(STR(?action)) = "sell")
        }
        GROUP BY ?investorId
    }

    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .
    FILTER(?investorId = ?investorId)
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName ;
              wm:hasCashFlow ?cashFlow ;
              wm:hasInvestmentGoal ?goal ;
              wm:hasRebalancingAction ?action ;
              wm:hasScenarioRebalancing ?scenarioRebalancing .

    ?cashFlow wm:type ?cashFlowType ;
              wm:date ?date .
    FILTER(LCASE(STR(?cashFlowType)) = "tax refund") .
    FILTER(xsd:date(?date) > "2026-04-28"^^xsd:date) .

    ?goal wm:investmentGoal ?goalType .
    FILTER(LCASE(STR(?goalType)) = "growth") .

    ?action wm:action ?actionType .
    FILTER(LCASE(STR(?actionType)) = "tactical") .

    ?scenarioRebalancing wm:scenario ?scenario .
    FILTER(LCASE(STR(?scenario)) = "bull market") .
}
GROUP BY ?investorId ?investorName

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
    ?investor a wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName ;
              wm:hasPortfolioHealth ?health ;
              wm:hasInvestmentGoal ?goal .

    ?health a wm:PortfolioHealth ;
            wm:liquidityScore ?liquidityScoreRaw .
    FILTER(xsd:decimal(?liquidityScoreRaw) < 20) .

    ?goal a wm:InvestmentGoal ;
          wm:targetAmount ?targetAmountRaw ;
          wm:currentValue ?currentValueRaw .
    BIND(xsd:decimal(?targetAmountRaw) - xsd:decimal(?currentValueRaw) AS ?shortfall) .
    FILTER(?shortfall > 0) .

    FILTER NOT EXISTS {
        ?goal wm:timeToGoalMonths ?timeToGoalMonthsRaw .
    }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskToleranceLabel
    ?investmentGoalTypeLabel
    (COUNT(DISTINCT ?goalId) AS ?goalCount)
WHERE {
    {
        SELECT ?goalId ?riskTolerance ?investmentGoalType
        WHERE {
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:goalId ?goalId ;
                  wm:belongsToInvestor ?investor ;
                  wm:hasInvestmentGoalType ?investmentGoalType .
            ?investor wm:hasRiskTolerance ?riskTolerance .
        }
        GROUP BY ?goalId ?riskTolerance ?investmentGoalType
    }
    ?riskTolerance rdfs:label ?riskToleranceLabel .
    ?investmentGoalType rdfs:label ?investmentGoalTypeLabel .
}
GROUP BY ?riskToleranceLabel ?investmentGoalTypeLabel
